CREATE OR REPLACE FUNCTION public.accept_proposal_by_token(_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  p public.internal_proposals;
  new_deal_id uuid;
  mid_value numeric;
BEGIN
  SELECT * INTO p FROM public.internal_proposals WHERE accept_token = _token LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_TOKEN');
  END IF;

  IF p.status = 'accepted' THEN
    RETURN jsonb_build_object('ok', true, 'already_accepted', true, 'proposal_id', p.id, 'deal_id', p.deal_id);
  END IF;

  IF p.status IN ('rejected','expired') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PROPOSAL_'|| upper(p.status::text));
  END IF;

  -- Estimate mid-point for the deal value
  mid_value := 50000; -- safe fallback

  UPDATE public.internal_proposals
     SET status = 'accepted', accepted_at = now(), updated_at = now()
   WHERE id = p.id;

  -- Create the deal (handle_deal_won trigger will create the invoice + flip contact to CLIENT)
  IF p.deal_id IS NULL THEN
    INSERT INTO public.deals (
      contact_id, business_name, deal_name,
      estimated_value_min, estimated_value_max, currency,
      status, notes, won_at
    ) VALUES (
      p.contact_id,
      COALESCE(p.business_name,''),
      COALESCE(NULLIF(p.title,''), 'Accepted proposal') ,
      mid_value, mid_value, 'GBP',
      'WON', 'Auto-created from accepted proposal ' || p.id::text, now()
    ) RETURNING id INTO new_deal_id;

    UPDATE public.internal_proposals SET deal_id = new_deal_id WHERE id = p.id;
  ELSE
    UPDATE public.deals SET status = 'WON', won_at = COALESCE(won_at, now()), updated_at = now()
     WHERE id = p.deal_id;
    new_deal_id := p.deal_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'proposal_id', p.id, 'deal_id', new_deal_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.log_demo_event(_token text, _event_type text, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  d public.demo_access;
  ev_type public.demo_event_type;
  duration int := 0;
BEGIN
  SELECT * INTO d FROM public.demo_access WHERE demo_token = _token LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'INVALID_TOKEN'); END IF;

  IF d.status <> 'active' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'DEMO_'|| upper(d.status::text));
  END IF;

  IF d.expires_at < now() THEN
    UPDATE public.demo_access SET status = 'expired', updated_at = now() WHERE id = d.id;
    RETURN jsonb_build_object('ok', false, 'error', 'DEMO_EXPIRED');
  END IF;

  BEGIN
    ev_type := _event_type::public.demo_event_type;
  EXCEPTION WHEN invalid_text_representation THEN
    ev_type := 'view';
  END;

  duration := COALESCE((_metadata->>'session_duration_seconds')::int, 0);

  INSERT INTO public.demo_events (demo_id, event_type, metadata, session_duration_seconds)
  VALUES (d.id, ev_type, COALESCE(_metadata,'{}'::jsonb), duration);

  UPDATE public.demo_access
     SET access_count = access_count + 1,
         last_accessed_at = now(),
         high_intent = (access_count + 1) >= 2,
         updated_at = now()
   WHERE id = d.id;

  RETURN jsonb_build_object('ok', true, 'demo_id', d.id, 'access_count', d.access_count + 1);
END;
$function$

CREATE OR REPLACE FUNCTION public.supplier_login_with_token(_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  su public.supplier_users;
  s  public.suppliers;
BEGIN
  SELECT * INTO su FROM public.supplier_users
   WHERE access_token = _token AND active = true LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_TOKEN');
  END IF;

  SELECT * INTO s FROM public.suppliers WHERE id = su.supplier_id;
  IF NOT FOUND OR s.status NOT IN ('APPROVED','QUALIFIED','CONTACTED','NEW') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SUPPLIER_INACTIVE');
  END IF;

  UPDATE public.supplier_users
     SET last_login_at = now(), updated_at = now()
   WHERE id = su.id;

  -- Heartbeat
  UPDATE public.suppliers SET last_activity_at = now(), updated_at = now()
   WHERE id = s.id;

  INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
  VALUES ('supplier_portal_login',
          'Supplier portal login: ' || s.name,
          'supplier_user', su.id);

  RETURN jsonb_build_object(
    'ok', true,
    'supplier_user_id', su.id,
    'supplier_id', s.id,
    'supplier_name', s.name,
    'supplier_email', su.email,
    'business_name', s.business_name,
    'role', s.role,
    'status', s.status
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.supplier_update_assignment_status(_token text, _assignment_id uuid, _new_status text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  su public.supplier_users;
  a  public.assignments;
  target_status assignment_status;
BEGIN
  SELECT * INTO su FROM public.supplier_users
   WHERE access_token = _token AND active = true LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_TOKEN');
  END IF;

  IF _new_status NOT IN ('in_progress','completed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_STATUS',
                              'allowed', jsonb_build_array('in_progress','completed'));
  END IF;
  target_status := _new_status::assignment_status;

  SELECT * INTO a FROM public.assignments
   WHERE id = _assignment_id AND supplier_id = su.supplier_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ASSIGNMENT_NOT_FOUND');
  END IF;
  IF a.status IN ('completed','failed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ASSIGNMENT_LOCKED', 'status', a.status);
  END IF;

  UPDATE public.assignments
     SET status = target_status,
         supplier_note = COALESCE(_note, supplier_note),
         acknowledged_at = COALESCE(acknowledged_at,
            CASE WHEN target_status = 'in_progress' THEN now() ELSE NULL END),
         updated_at = now()
   WHERE id = _assignment_id;

  -- Heartbeat
  UPDATE public.suppliers SET last_activity_at = now(), updated_at = now()
   WHERE id = su.supplier_id;

  INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
  VALUES ('supplier_status_update',
          'Supplier ' || COALESCE((SELECT name FROM public.suppliers WHERE id = su.supplier_id), su.email)
            || ' set assignment to ' || _new_status
            || COALESCE(' — ' || _note, ''),
          'assignment', _assignment_id);

  RETURN jsonb_build_object('ok', true, 'assignment_id', _assignment_id, 'status', _new_status);
END;
$function$
